Installation
Add to your deps.edn:
{:deps {org.scicloj/harmonica {:mvn/version "0.1.0"}}}

All groups under test
We test a diverse collection: small and large cyclic, symmetric, dihedral, and product groups.

(def all-groups
  [{:label "Z/1Z" :group (hm/cyclic-group 1)}
   {:label "Z/2Z" :group (hm/cyclic-group 2)}
   {:label "Z/3Z" :group (hm/cyclic-group 3)}
   {:label "Z/7Z" :group (hm/cyclic-group 7)}
   {:label "Z/12Z" :group (hm/cyclic-group 12)}
   {:label "S_1" :group (hm/symmetric-group 1)}
   {:label "S_2" :group (hm/symmetric-group 2)}
   {:label "S_3" :group (hm/symmetric-group 3)}
   {:label "S_4" :group (hm/symmetric-group 4)}
   {:label "S_5" :group (hm/symmetric-group 5)}
   {:label "D_3" :group (hm/dihedral-group 3)}
   {:label "D_4" :group (hm/dihedral-group 4)}
   {:label "D_5" :group (hm/dihedral-group 5)}
   {:label "D_6" :group (hm/dihedral-group 6)}
   {:label "D_8" :group (hm/dihedral-group 8)}
   {:label "D_12" :group (hm/dihedral-group 12)}
   {:label "Z/2Z × Z/2Z" :group (hm/product-group (hm/cyclic-group 2) (hm/cyclic-group 2))}
   {:label "Z/2Z × Z/3Z" :group (hm/product-group (hm/cyclic-group 2) (hm/cyclic-group 3))}
   {:label "Z/3Z × Z/4Z" :group (hm/product-group (hm/cyclic-group 3) (hm/cyclic-group 4))}
   {:label "D_3 × Z/2Z" :group (hm/product-group (hm/dihedral-group 3) (hm/cyclic-group 2))}])

(def test-groups
  "A collection of groups for systematic testing."
  [{:label "Z/2Z" :group (hm/cyclic-group 2) :has-ct? true}
   {:label "Z/5Z" :group (hm/cyclic-group 5) :has-ct? true}
   {:label "Z/7Z" :group (hm/cyclic-group 7) :has-ct? true}
   {:label "Z/12Z" :group (hm/cyclic-group 12) :has-ct? true}
   {:label "S_3" :group (hm/symmetric-group 3) :has-ct? true}
   {:label "S_4" :group (hm/symmetric-group 4) :has-ct? true}
   {:label "S_5" :group (hm/symmetric-group 5) :has-ct? true}
   {:label "D_3" :group (hm/dihedral-group 3) :has-ct? true}
   {:label "D_4" :group (hm/dihedral-group 4) :has-ct? true}
   {:label "D_5" :group (hm/dihedral-group 5) :has-ct? true}
   {:label "D_6" :group (hm/dihedral-group 6) :has-ct? true}
   {:label "D_8" :group (hm/dihedral-group 8) :has-ct? true}
   {:label "Z/2Z × Z/3Z" :group (hm/product-group
                                 (hm/cyclic-group 2)
                                 (hm/cyclic-group 3)) :has-ct? false}
   {:label "Z/2Z × Z/2Z" :group (hm/product-group
                                 (hm/cyclic-group 2)
                                 (hm/cyclic-group 2)) :has-ct? false}
   {:label "Z/3Z × Z/4Z" :group (hm/product-group
                                 (hm/cyclic-group 3)
                                 (hm/cyclic-group 4)) :has-ct? false}])


(def ct-groups
  "Groups that have character-table implementations."
  (filterv :has-ct? test-groups))
